108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        String address = normalizeAddress(ownerFieldsDto.getAddress());
112	        List<String> missingFields = new ArrayList<>();
113	        if (isBlank(ownerFieldsDto.getFirstName())) {
114	            missingFields.add("firstName");
115	        }
116	        if (isBlank(ownerFieldsDto.getLastName())) {
117	            missingFields.add("lastName");
118	        }
119	        if (isBlank(address)) {
120	            missingFields.add("address");
121	        }
122	        if (isBlank(ownerFieldsDto.getCity())) {
123	            missingFields.add("city");
124	        }
125	        if (isBlank(ownerFieldsDto.getTelephone())) {
126	            missingFields.add("telephone");
127	        }
128	        if (!missingFields.isEmpty()) {
129	            throw new MissingOwnerFieldsException(missingFields);
130	        }
131	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
132	        if (isTelephoneInUse(telephone)) {
133	            throw new DuplicateTelephoneException(ownerFieldsDto.getTelephone());
134	        }
135	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
136	        if (!sharesHousehold
137	            && isHouseholdInUse(ownerFieldsDto.getLastName(), address)) {
138	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), address);
139	        }
140	        if (isCityAtCapacity(ownerFieldsDto.getCity())) {
141	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
142	        }
143	        HttpHeaders headers = new HttpHeaders();
144	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
145	        owner.setAddress(address);
146	        owner.setTelephone(telephone);
147	        LocalDate effectiveDate = owner.getRegistrationDate() != null
148	            ? owner.getRegistrationDate() : LocalDate.now();
149	        LocalDate registrationDate = toBusinessDay(effectiveDate);
150	        if (isDailyRegistrationLimitReached(registrationDate)) {
151	            throw new DailyRegistrationLimitException(registrationDate);
152	        }
153	        owner.setRegistrationDate(registrationDate);
154	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
155	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
156	        if (sharesHousehold) {
157	            owner.setHouseholdId(joinHousehold(owner.getLastName(), owner.getAddress()));
158	        }
159	        this.clinicService.saveOwner(owner);
160	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
161	        headers.setLocation(UriComponentsBuilder.newInstance()
162	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
163	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
169	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
170	        if (currentOwner == null) {
171	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
172	        }
173	        currentOwner.setAddress(ownerFieldsDto.getAddress());
174	        currentOwner.setCity(ownerFieldsDto.getCity());
175	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
176	        currentOwner.setLastName(ownerFieldsDto.getLastName());
177	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
178	        this.clinicService.saveOwner(currentOwner);
179	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
180	    }
