257	    }
258	
259	    private static boolean isBlank(String value) {
260	        return value == null || value.isBlank();
261	    }
262	
263	    /**
264	     * Normalizes a street address into the canonical form stored on and returned for a newly
265	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
266	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
267	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
268	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
269	     * value is what gets persisted, echoed back, and used for every address comparison (household
270	     * duplicate detection and the shared household identifier).
271	     *
272	     * @param rawAddress the address value as supplied by the client
273	     * @return the normalized address (possibly empty, never {@code null})
274	     */
275	    private static String normalizeAddress(String rawAddress) {
276	        if (rawAddress == null) {
277	            return "";
278	        }
279	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
280	        if (collapsed.isEmpty()) {
281	            return "";
282	        }
283	        String[] tokens = collapsed.split(" ");
284	        StringBuilder sb = new StringBuilder(collapsed.length());
285	        for (int i = 0; i < tokens.length; i++) {
286	            String token = tokens[i];
287	            switch (token) {
288	                case "ST" -> token = "STREET";
289	                case "RD" -> token = "ROAD";
290	                case "AVE" -> token = "AVENUE";
291	                default -> { }
292	            }
293	            if (i > 0) {
294	                sb.append(' ');
295	            }
296	            sb.append(token);
297	        }
298	        return sb.toString();
299	    }
300	
301	    /**
302	     * Builds the customer code assigned to a newly created owner. The code is formatted
303	     * {@code <CITY3>-<LAST3>-<NNNN>} where {@code CITY3} is the upper-cased first three letters
304	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's
305	     * last name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more
306	     * than the number of owners already in that city (e.g. {@code LON-SMI-0007}).
307	     *
308	     * @param city the city of the owner being created
309	     * @param lastName the last name of the owner being created
310	     * @return the customer code to assign
311	     */
312	    private String nextCustomerCode(String city, String lastName) {
313	        String city3 = letterPrefix3(city);
314	        String last3 = letterPrefix3(lastName);
315	        String normalizedCity = normalizeIdentity(city);
316	        long sequence = this.clinicService.findAllOwners().stream()
317	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
318	            .count() + 1L;
319	        return String.format("%s-%s-%04d", city3, last3, sequence);
320	    }
321	
322	    /**
323	     * Returns the upper-cased first three letters of the given value, skipping any non-letter
324	     * characters. Values with fewer than three letters yield a shorter prefix.
325	     *
326	     * @param value the source text
327	     * @return the upper-cased letter prefix (at most three characters, never {@code null})
328	     */
329	    private static String letterPrefix3(String value) {
330	        StringBuilder prefix = new StringBuilder(3);
331	        if (value != null) {
332	            for (int i = 0; i < value.length() && prefix.length() < 3; i++) {
333	                char c = value.charAt(i);
334	                if (Character.isLetter(c)) {
335	                    prefix.append(Character.toUpperCase(c));
336	                }
337	            }
338	        }
339	        return prefix.toString();
340	    }
341	
342	    /**
343	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
344	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
345	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
346	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits.
347	     *
348	     * @param rawTelephone the telephone value as supplied by the client
349	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
350	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
351	     */
352	    private static String normalizeTelephone(String rawTelephone) {
353	        if (rawTelephone == null) {
354	            throw new InvalidTelephoneException(rawTelephone);
355	        }
356	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
357	        String e164;
358	        if (cleaned.startsWith("+")) {
359	            String digits = cleaned.substring(1);
360	            if (!digits.matches("[0-9]+")) {
361	                throw new InvalidTelephoneException(rawTelephone);
362	            }
363	            e164 = "+" + digits;
364	        } else {
365	            if (!cleaned.matches("[0-9]+")) {
366	                throw new InvalidTelephoneException(rawTelephone);
367	            }
368	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
369	            e164 = "+61" + national;
370	        }
371	        int digitCount = e164.length() - 1;
372	        if (digitCount < 8 || digitCount > 15) {
373	            throw new InvalidTelephoneException(rawTelephone);
374	        }
375	        return e164;
376	    }
377	
378	    /**
379	     * Determines whether any existing owner already uses the given E.164 telephone. Stored
380	     * telephones are themselves E.164, so the values are compared directly.
381	     *
382	     * @param e164Telephone the E.164 telephone of the owner being created
383	     * @return {@code true} if another owner already has the same E.164 telephone
384	     */
385	    private boolean isTelephoneInUse(String e164Telephone) {
386	        return this.clinicService.findAllOwners().stream()
387	            .map(Owner::getTelephone)
388	            .filter(existing -> existing != null)
389	            .anyMatch(e164Telephone::equals);
390	    }
391	
392	    /**
393	     * Determines whether any existing owner already shares a household with the owner being created,
394	     * i.e. has both the same last name and the same address. Both fields are compared
395	     * case-insensitively after collapsing runs of whitespace to a single space and trimming.
396	     *
397	     * @param lastName the last name of the owner being created
398	     * @param address the address of the owner being created
399	     * @return {@code true} if another owner already has the same last name and address
400	     */
401	    private boolean isHouseholdInUse(String lastName, String address) {
402	        String normalizedLastName = normalizeIdentity(lastName);
403	        String normalizedAddress = normalizeIdentity(address);
404	        return this.clinicService.findAllOwners().stream()
405	            .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
406	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress));
407	    }
408	
409	    /**
410	     * Counts how many existing owners already share the given first name and last name with the
411	     * owner being created. Both names are compared case-insensitively (after trimming and
412	     * collapsing runs of whitespace). The count reflects the state before the new owner is
413	     * persisted, so a first, otherwise-unique owner yields {@code 0}.
414	     *
415	     * @param firstName the first name of the owner being created
416	     * @param lastName the last name of the owner being created
417	     * @return the number of existing owners sharing the same first and last name
418	     */
419	    private int namesakeCount(String firstName, String lastName) {
420	        String normalizedFirstName = normalizeIdentity(firstName);
421	        String normalizedLastName = normalizeIdentity(lastName);
422	        return (int) this.clinicService.findAllOwners().stream()
423	            .filter(existing -> normalizeIdentity(existing.getFirstName()).equals(normalizedFirstName)
424	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName))
425	            .count();
426	    }
427	
428	    /**
429	     * The maximum number of owners permitted in a single city. Once a city already contains this
430	     * many owners it is considered full and no further owners may be created there.
431	     */
432	    private static final int CITY_CAPACITY = 50;
433	
434	    /**
435	     * Determines whether the given city has already reached its capacity, i.e. already contains
436	     * {@value #CITY_CAPACITY} or more existing owners. Cities are compared case-insensitively after
437	     * collapsing runs of whitespace to a single space and trimming.
438	     *
439	     * @param city the city of the owner being created
440	     * @return {@code true} if the city already contains {@value #CITY_CAPACITY} or more owners
441	     */
442	    private boolean isCityAtCapacity(String city) {
443	        String normalizedCity = normalizeIdentity(city);
444	        long count = this.clinicService.findAllOwners().stream()
445	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
446	            .count();
447	        return count >= CITY_CAPACITY;
448	    }
449	
450	    /**
451	     * The maximum number of owners that may be created on any single day. Once this many owners
452	     * already carry a {@code registrationDate} of the current day, no further owners may be created
453	     * that day.
454	     */
455	    private static final int DAILY_REGISTRATION_LIMIT = 100;
456	
457	    /**
458	     * Determines whether the daily registration limit has already been reached, i.e. whether
459	     * {@value #DAILY_REGISTRATION_LIMIT} or more existing owners already carry the given date as
460	     * their {@code registrationDate}.
461	     *
462	     * @param date the current day
463	     * @return {@code true} if {@value #DAILY_REGISTRATION_LIMIT} or more owners were already
464	     *         registered on the given date
465	     */
466	    /**
467	     * Rolls a registration date forward onto a business day. A date that already falls on a
468	     * weekday is returned unchanged; a Saturday or Sunday is rolled forward to the following
469	     * Monday. This adjusted date is what gets stored as the {@code registrationDate} and drives
470	     * everything derived from it (the membership number's year segment, the daily create-limit).
471	     *
472	     * @param date the effective registration date (supplied by the client or defaulted to the
473	     *             server's current date)
474	     * @return the same date if it is a weekday, otherwise the following Monday
475	     */
476	    private static LocalDate toBusinessDay(LocalDate date) {
477	        DayOfWeek dayOfWeek = date.getDayOfWeek();
478	        if (dayOfWeek == DayOfWeek.SATURDAY) {
479	            return date.plusDays(2);
480	        }
481	        if (dayOfWeek == DayOfWeek.SUNDAY) {
482	            return date.plusDays(1);
483	        }
484	        return date;
485	    }
486	
487	    private boolean isDailyRegistrationLimitReached(LocalDate date) {
488	        long count = this.clinicService.findAllOwners().stream()
489	            .filter(existing -> date.equals(existing.getRegistrationDate()))
490	            .count();
491	        return count >= DAILY_REGISTRATION_LIMIT;
492	    }
493	
494	    /**
495	     * Assigns the owner being created to the household identified by the given last name and
496	     * address and returns the household's stable shared identifier. The identifier is derived
497	     * deterministically from the normalized last name and address, so every member of the same
498	     * household resolves to the same value regardless of creation order. Any existing member that
499	     * does not yet carry the identifier is back-filled so all household members share it.
500	     *
501	     * @param lastName the last name of the owner being created
502	     * @param address the address of the owner being created
503	     * @return the stable household identifier shared by all members of the household
504	     */
505	    private String joinHousehold(String lastName, String address) {
506	        String householdId = householdIdFor(lastName, address);
507	        String normalizedLastName = normalizeIdentity(lastName);
508	        String normalizedAddress = normalizeIdentity(address);
509	        for (Owner existing : this.clinicService.findAllOwners()) {
510	            if (normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
511	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress)
512	                && !householdId.equals(existing.getHouseholdId())) {
513	                existing.setHouseholdId(householdId);
514	                this.clinicService.saveOwner(existing);
515	            }
516	        }
517	        return householdId;
518	    }
519	
520	    /**
521	     * Derives the stable household identifier for a given last name and address. The value is the
522	     * first 16 upper-case hex characters of the SHA-256 digest of the normalized last name and
523	     * address, so it is stable across calls and identical for every member of the household.
524	     *
525	     * @param lastName the last name of the household
526	     * @param address the address of the household
527	     * @return the stable household identifier
528	     */
529	    private static String householdIdFor(String lastName, String address) {
530	        String key = normalizeIdentity(lastName) + "\n" + normalizeIdentity(address);
531	        try {
532	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
533	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
534	            StringBuilder sb = new StringBuilder(digest.length * 2);
535	            for (byte b : digest) {
536	                sb.append(String.format("%02x", b));
537	            }
538	            return sb.substring(0, 16).toUpperCase(java.util.Locale.ROOT);
539	        }
540	        catch (java.security.NoSuchAlgorithmException e) {
541	            throw new IllegalStateException("SHA-256 not available", e);
542	        }
543	    }
544	
545	    /**
546	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
547	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
548	     * single space, and the result is lower-cased.
549	     *
550	     * @param value the raw field value
551	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
552	     */
553	    private static String normalizeIdentity(String value) {
554	        if (value == null) {
555	            return "";
556	        }
557	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
558	    }
559	}
